-- Opportunities cell (opportunities), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA opportunities;

CREATE FUNCTION opportunities.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE opportunities.opportunities (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) >= 1),
    description              text,
    type                     text CHECK (type IS NULL OR (type IN ('ai_automation', 'saas', 'service', 'content', 'consulting', 'product', 'other'))),
    tier                     integer,
    status                   text NOT NULL DEFAULT 'researching' CHECK (status IN ('researching', 'validating', 'active', 'paused', 'killed', 'completed')),
    pain_level               integer,
    budget_level             integer,
    frequency_level          integer,
    ai_leverage_level        integer,
    competition_level        integer,
    distribution_level       integer,
    fit_level                integer,
    total_score              double precision,
    window_status            text CHECK (window_status IS NULL OR (window_status IN ('opening', 'open', 'narrowing', 'closed'))),
    estimated_window_months  integer,
    target_market            text,
    revenue_model            text,
    price_range              text,
    competitors              text,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX opportunities_legacy ON opportunities.opportunities (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX opportunities_status ON opportunities.opportunities (workspace_id, status);
CREATE INDEX opportunities_type ON opportunities.opportunities (workspace_id, type);
CREATE INDEX opportunities_window_status ON opportunities.opportunities (workspace_id, window_status);

CREATE TABLE opportunities.opportunity_actions (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    url                      text NOT NULL CHECK (length(url) >= 1),
    title                    text,
    source                   text,
    category                 text,
    trend_score              integer,
    action                   text NOT NULL DEFAULT 'monitor' CHECK (action IN ('act_on', 'skip', 'monitor')),
    action_notes             text,
    revenue_actual           double precision NOT NULL DEFAULT 0.0,
    revenue_expected         double precision NOT NULL DEFAULT 0.0,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX opportunity_actions_legacy ON opportunities.opportunity_actions (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX opportunity_actions_action ON opportunities.opportunity_actions (workspace_id, action);
CREATE INDEX opportunity_actions_category ON opportunities.opportunity_actions (workspace_id, category);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE opportunities.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('opportunity', 'opportunity-action')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE opportunities.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON opportunities.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['opportunities', 'opportunity_actions', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE opportunities.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE opportunities.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON opportunities.%I'
                       ' USING (workspace_id = opportunities.current_workspace())'
                       ' WITH CHECK (workspace_id = opportunities.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA opportunities TO opportunities_api;
GRANT EXECUTE ON FUNCTION opportunities.current_workspace() TO opportunities_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON opportunities.opportunities, opportunities.opportunity_actions TO opportunities_api;
GRANT USAGE ON SEQUENCE opportunities.opportunities_id_seq, opportunities.opportunity_actions_id_seq TO opportunities_api;
GRANT SELECT, INSERT ON opportunities.create_keys TO opportunities_api;
GRANT SELECT, INSERT ON opportunities.outbox TO opportunities_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON opportunities.outbox TO opportunities_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON opportunities.outbox TO opportunities_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA opportunities TO opportunities_publisher;
GRANT SELECT ON opportunities.outbox TO opportunities_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON opportunities.outbox TO opportunities_publisher;
